CREATE TABLE IF NOT EXISTS market_monitoring_snapshots (id text PRIMARY KEY, source_id text NOT NULL REFERENCES market_sources(source_id), run_id text NOT NULL REFERENCES market_source_runs(id), region_code text NOT NULL, goods_code text NOT NULL, product_name text NOT NULL, variant text NOT NULL, latest_reference_date date NOT NULL, raw_hash text NOT NULL, payload jsonb NOT NULL, collected_at timestamptz NOT NULL DEFAULT now(), UNIQUE(source_id,raw_hash));
